import json, glob
for f in glob.glob('/tmp/sweagent-dataset-*/*/dataset.json'):
    try:
        d=json.load(open(f))
    except Exception as e:
        print('ERR', f, e); continue
    if not isinstance(d, list):
        d=[d]
    for item in d:
        if not isinstance(item, dict): continue
        # look at all string values
        s=json.dumps(item)
        if 'COUNTIFS' in s:
            print('COUNTIFS in', f, item.get('task_id') or item.get('id'))
        if 'PL' in s and 'Statement' in s:
            print('PL+Statement in', f, item.get('task_id') or item.get('id'))
        if '52633' in s:
            print('52633 in', f, item.get('task_id') or item.get('id'))
